{
  "id": "217021b9-e3da-4fbb-aeb5-1493d415ac5a",
  "version": "1.8",
  "name": "POReview",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "e7406c84-ee5e-46d9-ad62-ca4d70d0e6b1",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "fetchPO1",
      "type": "core.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Fetch PO Data"
      },
      "inputs": {
        "language": "javascript",
        "script": "// Retrieve PO details by PO number passed from the trigger.\n// In production, replace this with an HTTP call to your ERP / procurement system.\nconst poNumber = $vars.start.output.poNumber;\nreturn {\n  poNumber: poNumber || \"PO-2026-0042\",\n  vendor: \"Acme Supplies Ltd.\",\n  totalAmount: 12500.00,\n  requestedBy: \"Jane Smith\",\n  submissionDate: \"2026-07-24\",\n  description: \"Office equipment and supplies for Q3 operations\",\n  lineItems: \"3x Laptop ($3,000 each), 10x Keyboard ($50 each), Misc. supplies ($1,000)\"\n};"
      }
    },
    {
      "id": "poReview1",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "PO Review"
      },
      "inputs": {
        "title": "Purchase Order Review",
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        },
        "priority": "Medium",
        "schema": {
          "schemaId": "b8f3c2d1-9a4e-4f7b-a5c6-2d3e4f5a6b7c",
          "fields": [
            {
              "id": "ponumber",
              "label": "PO Number",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPO1.output.poNumber"
            },
            {
              "id": "vendor",
              "label": "Vendor",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPO1.output.vendor"
            },
            {
              "id": "totalamount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchPO1.output.totalAmount"
            },
            {
              "id": "requestedby",
              "label": "Requested By",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPO1.output.requestedBy"
            },
            {
              "id": "submissiondate",
              "label": "Submission Date",
              "type": "date",
              "direction": "input",
              "binding": "vars.fetchPO1.output.submissionDate"
            },
            {
              "id": "description",
              "label": "Description",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPO1.output.description"
            },
            {
              "id": "lineitems",
              "label": "Line Items",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPO1.output.lineItems"
            },
            {
              "id": "notes",
              "label": "Notes",
              "type": "string",
              "direction": "output",
              "variable": "vars.reviewNotes",
              "required": false
            }
          ],
          "outcomes": [
            { "id": "approve",  "name": "Approve",  "type": "string", "isPrimary": true,  "action": "Continue" },
            { "id": "reject",   "name": "Reject",   "type": "string", "isPrimary": false, "action": "End" },
            { "id": "escalate", "name": "Escalate", "type": "string", "isPrimary": false, "action": "End" }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "notes":  { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject", "Escalate"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject", "Escalate"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "routeDecision1",
      "type": "core.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Route Decision"
      },
      "inputs": {
        "language": "javascript",
        "script": "// Read the reviewer's decision and notes, then log the final routed outcome.\n// Extend this node to call downstream systems (ERP approval, rejection email, escalation queue, etc.)\nconst decision = $vars.poReview1.status;\nconst notes = $vars.poReview1.output.notes;\nconst poNumber = $vars.fetchPO1.output.poNumber;\nconst totalAmount = $vars.fetchPO1.output.totalAmount;\nreturn {\n  decision: decision,\n  poNumber: poNumber,\n  totalAmount: totalAmount,\n  notes: notes,\n  message: `PO ${poNumber} ($${totalAmount}) → ${decision}. Reviewer notes: ${notes || '(none)'}`\n};"
      }
    }
  ],
  "edges": [
    {
      "id": "start-output-fetchPO1-input",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "fetchPO1",
      "targetPort": "input"
    },
    {
      "id": "fetchPO1-output-poReview1-input",
      "sourceNodeId": "fetchPO1",
      "sourcePort": "output",
      "targetNodeId": "poReview1",
      "targetPort": "input"
    },
    {
      "id": "poReview1-completed-routeDecision1-input",
      "sourceNodeId": "poReview1",
      "sourcePort": "completed",
      "targetNodeId": "routeDecision1",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start workflow manually",
      "tags": [
        "trigger",
        "start",
        "manual"
      ],
      "sortOrder": 40,
      "display": {
        "label": "Manual trigger",
        "icon": "play",
        "shape": "circle"
      },
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            {
              "id": "output",
              "type": "source",
              "handleType": "output",
              "showButton": true,
              "constraints": {
                "forbiddenTargetCategories": [
                  "trigger"
                ]
              }
            }
          ],
          "visible": true
        }
      ],
      "model": {
        "type": "bpmn:StartEvent",
        "entryPointId": true
      },
      "outputDefinition": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      },
      "toolbarExtensions": {
        "design": {
          "actions": [
            {
              "id": "change-trigger-type",
              "icon": "square-mouse-pointer",
              "label": "Change trigger type"
            }
          ]
        }
      }
    },
    {
      "nodeType": "uipath.human-in-the-loop.quick-form",
      "version": "1.0",
      "category": "human-task",
      "description": "Fast inline approvals with inline debug",
      "tags": ["human-task", "hitl", "human-in-the-loop", "quick-form", "approval"],
      "sortOrder": 27,
      "display": {
        "label": "Quick Form",
        "icon": "users",
        "shape": "square"
      },
      "handleConfiguration": [
        {
          "position": "left",
          "handles": [
            {
              "id": "input",
              "type": "target",
              "handleType": "input"
            }
          ],
          "visible": true
        },
        {
          "position": "right",
          "handles": [
            {
              "id": "completed",
              "label": "Completed",
              "type": "source",
              "handleType": "output",
              "showButton": true,
              "constraints": { "forbiddenTargetCategories": ["trigger"] }
            }
          ],
          "visible": true
        }
      ],
      "model": { "type": "bpmn:UserTask", "serviceType": "Actions.HITL" },
      "inputDefaults": {
        "schema": {
          "fields": [],
          "outcomes": [{ "id": "submit", "name": "Submit", "type": "string", "isPrimary": true, "action": "Continue" }]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        }
      },
      "outputDefinition": {
        "output": { "type": "object", "description": "Task result data", "source": "=result", "var": "output" },
        "status": { "type": "string", "description": "Task completion status", "source": "=result.Action", "var": "status" }
      }
    }
  ],
  "variables": {
    "nodes": [
      {
        "id": "start.output",
        "type": "object",
        "description": "Data passed when manually triggering the workflow.",
        "binding": { "nodeId": "start", "outputId": "output" }
      },
      {
        "id": "fetchPO1.output",
        "type": "object",
        "description": "Fetch PO Data output",
        "binding": { "nodeId": "fetchPO1", "outputId": "output" }
      },
      {
        "id": "poReview1.output",
        "type": "object",
        "description": "Task result data",
        "binding": { "nodeId": "poReview1", "outputId": "output" }
      },
      {
        "id": "poReview1.status",
        "type": "string",
        "description": "Task completion status",
        "binding": { "nodeId": "poReview1", "outputId": "status" }
      },
      {
        "id": "routeDecision1.output",
        "type": "object",
        "description": "Route Decision output",
        "binding": { "nodeId": "routeDecision1", "outputId": "output" }
      }
    ]
  },
  "layout": {
    "nodes": {
      "start":           { "position": { "x": 256, "y": 144 } },
      "fetchPO1":        { "position": { "x": 480, "y": 144 } },
      "poReview1":       { "position": { "x": 720, "y": 144 } },
      "routeDecision1":  { "position": { "x": 960, "y": 144 } }
    }
  }
}

